// 1. Install: npm install -D @tailwindcss/typography

// 2. Register Plugin
module.exports = {
  theme: {},
  plugins: [
    require('@tailwindcss/typography'),
  ],
}

// 3. Usage:
// If a backend CMS gives you raw HTML without any Tailwind classes,
// wrapping it in a 'prose' div instantly makes it beautiful and readable.
<article class="prose lg:prose-xl text-gray-800">
  <!-- Raw HTML from database goes here -->
  <div dangerouslySetInnerHTML={{ __html: cmsContent }} />
</article>
